CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, investigation_id TEXT NOT NULL REFERENCES investigations(id), owner_user_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, status TEXT NOT NULL, current_version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS report_versions (id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES reports(id), version_number INTEGER NOT NULL, status TEXT NOT NULL, sections_json TEXT NOT NULL, notes TEXT NOT NULL, html TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL, immutable INTEGER NOT NULL DEFAULT 0, UNIQUE(report_id,version_number));
CREATE TABLE IF NOT EXISTS report_reviews (id TEXT PRIMARY KEY, report_version_id TEXT NOT NULL REFERENCES report_versions(id), reviewer_user_id TEXT NOT NULL REFERENCES users(id), decision TEXT NOT NULL, note TEXT NOT NULL, created_at TEXT NOT NULL);
ALTER TABLE reports ADD COLUMN assigned_reviewer_id TEXT REFERENCES users(id);
